    c = S.counts(); ops = {'status': 0, 'block': 0, 'heaven': 0}; ops.update(c['ops'])
    RC = open(f'{SP}/ch32b_recon.out', encoding='utf-8').read()
    g = re.search(r"RUN = \((\d+), (\d+), (\d+), (\d+), (\d+), (\d+), (\d+), (\d+),", RC); assert g; RUN = [int(x) for x in g.groups()]
